using System.Text.Json;
using Application.Interfaces;
using MoonSharp.Interpreter;

namespace Infrastructure.Scripting;

public sealed class LuaRuleEvaluator : IRuleEvaluator
{
    public bool Evaluate(string luaScript, IReadOnlyDictionary<string, JsonElement> properties)
    {
        // Only scripts generated by LuaRuleCompiler are accepted. Do not expose this evaluator as an arbitrary Lua endpoint.
        var script = new Script(CoreModules.Preset_SoftSandbox);
        var context = new Table(script);
        foreach (var (key, value) in properties)
        {
            if (key.Length == 0 || key.Any(c => !(char.IsLetterOrDigit(c) || c == '_')) || char.IsDigit(key[0])) continue;
            context.Set(DynValue.NewString(key), ToDynValue(value));
        }
        var function = script.DoString(luaScript);
        var result = script.Call(function, DynValue.NewTable(context));
        return result.Type == DataType.Boolean && result.Boolean;
    }

    private static DynValue ToDynValue(JsonElement value) => value.ValueKind switch
    {
        JsonValueKind.Number => DynValue.NewNumber(value.GetDouble()),
        JsonValueKind.String => DynValue.NewString(value.GetString() ?? string.Empty),
        JsonValueKind.True => DynValue.NewBoolean(true),
        JsonValueKind.False => DynValue.NewBoolean(false),
        JsonValueKind.Null => DynValue.Nil,
        _ => DynValue.Nil
    };
}
